package org.apache.commons.lang.math;

import junit.framework.TestCase;

public class AgentBRT_Lang_58_raw_diff_Test extends TestCase {

    public void testReproduceBug() {
        // The bug was related to parsing long numbers with 'L' suffix.
        // The input "-0123L" should be parsed correctly as a Long.
        try {
            Number result = NumberUtils.createNumber("-0123L");
            assertTrue("Expected instance of Long, but got: " + result.getClass().getName(), result instanceof Long);
            assertEquals("Expected value -123, but got: " + result, -123L, ((Long) result).longValue());
        } catch (NumberFormatException e) {
            fail("NumberFormatException was thrown: " + e.getMessage());
        }
    }
}

